#!/bin/sh
# Vox-Pro build template — the director generates a film-specific copy.
# From opusflow root:  sh styles/vox-pro/template/build.sh
set -e
HERE=$(cd "$(dirname "$0")" && pwd)
LIB=${LIB:-$(cd "$HERE/../../.." && pwd)}
export LIB
[ -f "$LIB/core/render/video.mjs" ] || { echo "set LIB to opusflow root"; exit 1; }
cd "$LIB"

FILM_DIR="$HERE"
FPS=30
SIZE="1080x1920"
WORKERS=4

echo "=== Vox-Pro Template Build ==="
mkdir -p "$FILM_DIR/out/vo" "$FILM_DIR/stills"

# ── 1. VO concat ────────────────────────────────────────────────────────────
# Films generated by the director have per-scene MP3s in out/vo/
VO_FILES=$(ls "$FILM_DIR/out/vo/"line*.mp3 2>/dev/null | sort -V | tr '\n' ' ')
if [ -z "$VO_FILES" ]; then
  echo "No VO files found in $FILM_DIR/out/vo/ — skipping audio"
  HAVE_AUDIO=0
else
  HAVE_AUDIO=1
  # Build the adelay filter from timeline.json
  python3 - << 'PY'
import json, subprocess, sys, os, shlex
tl = json.load(open(os.path.join(os.environ['FILM_DIR'], 'timeline.json')))
scenes  = tl['scenes']
n       = len(scenes)
vo_dir  = os.path.join(os.environ['FILM_DIR'], 'out', 'vo')
out_dir = os.path.join(os.environ['FILM_DIR'], 'out')

inputs = []
for i in range(n):
    p = os.path.join(vo_dir, f'line{i+1}.mp3')
    if os.path.exists(p):
        inputs.append(p)
    else:
        sys.exit(f'Missing {p}')

delays = ';'.join(
    f'[{i}:a]adelay={int(s["start"]*1000)}|{int(s["start"]*1000)}[a{i+1}]'
    for i, s in enumerate(scenes)
)
amix_in = ''.join(f'[a{i+1}]' for i in range(n))
fc = f"{delays};{amix_in}amix=inputs={n}:normalize=0[out]"

cmd = ['ffmpeg', '-y', '-loglevel', 'error']
for p in inputs:
    cmd += ['-i', p]
cmd += ['-filter_complex', fc, '-map', '[out]', '-t', str(tl['dur']),
        '-ar', '48000', '-ac', '1', os.path.join(out_dir, 'vo_concat.wav')]
subprocess.run(cmd, check=True)
print('→ vo_concat.wav')
PY
fi

# ── 2. SFX + BGM ─────────────────────────────────────────────────────────────
if [ "$HAVE_AUDIO" = "1" ]; then
  FILM_DIR="$FILM_DIR" "$LIB/.venv/bin/python" "$FILM_DIR/mix.py"
  echo "→ sfxbgm.wav"

  # ── 3. Mix VO + SFX ───────────────────────────────────────────────────────
  DUR=$(python3 -c "import json; print(json.load(open('$FILM_DIR/timeline.json'))['dur'])")
  ffmpeg -y -loglevel error \
    -i "$FILM_DIR/out/vo_concat.wav" -i "$FILM_DIR/out/sfxbgm.wav" \
    -filter_complex "[0:a]volume=1.0[vo];[1:a]volume=0.251[bg];[vo][bg]amix=inputs=2:normalize=0[out]" \
    -map "[out]" -t "$DUR" -ar 48000 -ac 1 \
    "$FILM_DIR/out/mix.wav"
  echo "→ mix.wav"
fi

# ── 4. Render picture ────────────────────────────────────────────────────────
node "$LIB/core/render/video.mjs" "$FILM_DIR" \
  --fps $FPS --size $SIZE --workers $WORKERS \
  --out "$FILM_DIR/out/video.mp4"
echo "→ video.mp4"

# ── 5. Mux ───────────────────────────────────────────────────────────────────
if [ "$HAVE_AUDIO" = "1" ]; then
  AUDIO_IN="$FILM_DIR/out/mix.wav"
else
  AUDIO_IN=""
fi
sh "$LIB/core/render/mux.sh" "$FILM_DIR/out/video.mp4" "$AUDIO_IN" \
  "$FILM_DIR/film.mp4" $FPS 2
echo "→ film.mp4"

# ── 6. QA stills ─────────────────────────────────────────────────────────────
python3 -c "
import json, subprocess, os, sys
tl = json.load(open('$FILM_DIR/timeline.json'))
for s in tl['scenes']:
    t = round((s['start'] + s['end'])/2, 2)
    out = '$FILM_DIR/stills/t_%s.jpg' % str(t).replace('.','_')
    subprocess.run([
        'node', '$LIB/core/render/still.mjs',
        '$FILM_DIR', str(t), '1',
        '--size', '1080x1920', '--out', out
    ], capture_output=True)
print('stills written')
"

echo ""
echo "=== Done: $FILM_DIR/film.mp4 ==="
